const frame=document.querySelector('.frame');const title=document.querySelector('#frame-title');const copy=document.querySelector('[data-copy]');const feedback=document.querySelector('.feedback');const labels={main:'江湖見聞',dialog:'行旅提示',special:'珍藏鑑賞'};document.querySelectorAll('[data-sample]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-sample]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));frame.dataset.frame=button.dataset.sample;title.textContent=labels[button.dataset.sample];feedback.textContent='';}));document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(item=>{item.setAttribute('aria-selected',String(item===button));item.tabIndex=item===button?0:-1});document.querySelector('#sample-panel').setAttribute('aria-labelledby',button.id);copy.textContent=button.dataset.tab==='long'?'山路迢迢，雲霧漸散。'.repeat(35):'青山如故，行路有伴。這是短內容的呈現範例。';}));document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>{feedback.textContent=button.dataset.action==='back'?'返回操作示意':'確認操作示意';}));

const tabs=[...document.querySelectorAll('[data-tab]')];document.querySelector('[role=tablist]').addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const current=tabs.indexOf(document.activeElement);const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(current+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();tabs[next].click();});
